/**
 * Regenerates `types/application-definition.d.ts` from `schemas/`.
 *
 * Run it with `mise run codegen` (or `npx tsx scripts/generate-types.ts`).
 * `mise run update` depends on this task, so a full codegen pass picks it up.
 *
 * WHY THIS EXISTS
 *
 * `types/application-definition.d.ts` carries the banner "generated by
 * json-schema-to-typescript ... modify the source JSONSchema file", but until
 * now neither the source schemas nor the generator lived in this repo -- the
 * schemas were a fork in david-driscoll/stargate-command-cluster and the
 * generator was an ad-hoc invocation that was never committed anywhere. The
 * types could therefore only be edited by hand, which is exactly what the
 * banner forbids, and they had already drifted from both the schemas and the
 * CRD.
 *
 * The chain the estate actually depends on is:
 *
 *   schemas/definition.schema.json   <- the `$schema` every definition.yaml
 *                                       points at, so it is what validates
 *                                       ApplicationDefinition in the editor
 *          |
 *          | (this script)
 *          v
 *   types/application-definition.d.ts <- what components/ and stacks/ compile
 *                                        against
 *
 *   kubernetes/apps/observability/crds/application-crd.yaml
 *                                     <- the API server's structural schema.
 *                                        It has NO
 *                                        x-kubernetes-preserve-unknown-fields,
 *                                        so any key missing from it is PRUNED
 *                                        on write and the Pulumi stack that
 *                                        renders the Gatus config never sees
 *                                        it. Keep it in step with
 *                                        schemas/gatus.schema.json by hand;
 *                                        `checkCrdParity` below fails the run
 *                                        if the Gatus endpoint key sets
 *                                        diverge.
 */

import { execFileSync } from "node:child_process";
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { compileFromFile } from "json-schema-to-typescript";
import * as yaml from "yaml";

const repoRoot = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const schemaDir = join(repoRoot, "schemas");
const outFile = join(repoRoot, "types", "application-definition.d.ts");
const crdFile = join(repoRoot, "kubernetes", "apps", "observability", "crds", "application-crd.yaml");

/**
 * Replaces json-schema-to-typescript's default banner.
 *
 * The `Roles` import and the four `export type` aliases below are consumed all
 * over components/ and stacks/ (`GatusDefinition`, `AuthentikDefinition`, ...).
 * They cannot be expressed in JSON Schema, so they live here rather than being
 * re-added by hand after every regeneration -- which is how they survived
 * before, and why the file said "DO NOT MODIFY IT BY HAND" while being modified
 * by hand.
 *
 * `RolesValues` is referenced from the schema itself via the `tsType` keyword
 * (see `access_policy.groups` in definition.schema.json).
 */
const banner = `/* eslint-disable */
/**
 * This file was automatically generated by scripts/generate-types.ts.
 * DO NOT MODIFY IT BY HAND. Instead, modify the source JSONSchema files under
 * schemas/ and run \`mise run codegen\`.
 */

import type { Roles } from "@components/constants.ts";

type RolesKeys = keyof typeof Roles;
type RolesValues = (typeof Roles)[RolesKeys];

export type ApplicationDefinition = ApplicationDefinitionSchema["spec"];
export type AuthentikDefinition = NonNullable<ApplicationDefinitionSchema["spec"]["authentik"]>;
export type GatusDefinition = Omit<NonNullable<ApplicationDefinitionSchema["spec"]["gatus"]>[number], "enabled">;
export type UptimeDefinition = NonNullable<ApplicationDefinitionSchema["spec"]["uptime"]>;
`;

/**
 * The Gatus endpoint keys the CRD accepts, and the ones the JSON Schema
 * describes, have to be the same set.
 *
 * A key in the schema but not the CRD is the dangerous direction: the editor
 * accepts it, TypeScript accepts it, and then the API server silently drops it
 * on `kubectl apply`. That is what `maintenance-windows` was before PR #1047.
 */
function checkCrdParity(): string[] {
  const crd = yaml.parse(readFileSync(crdFile, "utf-8"));
  const crdEndpoint = crd.spec.versions[0].schema.openAPIV3Schema.properties.spec.properties.gatus.items.properties;
  const schema = JSON.parse(readFileSync(join(schemaDir, "gatus.schema.json"), "utf-8"));
  const schemaEndpoint = schema.$defs.endpoint.properties;

  const inCrd = new Set(Object.keys(crdEndpoint));
  const inSchema = new Set(Object.keys(schemaEndpoint));
  const problems: string[] = [];
  for (const key of inSchema) {
    if (!inCrd.has(key)) {
      problems.push(`  gatus endpoint key "${key}" is in schemas/gatus.schema.json but NOT in the CRD -- the API server will prune it`);
    }
  }
  for (const key of inCrd) {
    if (!inSchema.has(key)) {
      problems.push(`  gatus endpoint key "${key}" is in the CRD but NOT in schemas/gatus.schema.json -- editors will flag it as unknown`);
    }
  }
  return problems;
}

const compiled = await compileFromFile(join(schemaDir, "definition.schema.json"), {
  cwd: `${schemaDir}/`,
  additionalProperties: false,
  bannerComment: banner,
  declareExternallyReferenced: true,
  // `ExternalEndpoint` (Gatus' `external-endpoints[]`) is not reachable from
  // the ApplicationDefinition spec -- nothing in the CRD carries one -- but
  // components/BackupPlanDirector.ts and stacks/backups/index.ts build them, so
  // definition.schema.json parks a `$defs.externalEndpoint` pointer for the
  // sole purpose of getting the interface emitted. That only happens with this
  // flag on.
  unreachableDefinitions: true,
  style: {
    printWidth: 140,
    semi: true,
    singleQuote: false,
    trailingComma: "all",
    arrowParens: "avoid",
    useTabs: false,
    tabWidth: 2,
  },
});

writeFileSync(outFile, compiled);

// biome owns formatting for everything outside sdks/ (see biome.json), and the
// hk pre-commit hook checks it. Normalising here keeps a fresh codegen from
// failing the very next commit.
execFileSync("npx", ["--no-install", "biome", "check", "--write", "--no-errors-on-unmatched", outFile], {
  cwd: repoRoot,
  stdio: "inherit",
});

console.log(`wrote ${outFile}`);

const problems = checkCrdParity();
if (problems.length > 0) {
  console.error("\nCRD / schema drift in the Gatus endpoint schema:");
  console.error(problems.join("\n"));
  console.error("\nFix kubernetes/apps/observability/crds/application-crd.yaml or schemas/gatus.schema.json so the two agree.");
  process.exit(1);
}
console.log("CRD and schema agree on the Gatus endpoint keys");
